var e=class{constructor(e){this.root=e}init(){this.root.addEventListener(`click`,e=>this.copyValue(e))}async copyValue(e){let t=e.target.closest(`[data-copy-value]`);if(t)try{await navigator.clipboard.writeText(t.dataset.copyValue),this.showCopiedState(t)}catch{this.copyWithFallback(t)}}copyWithFallback(e){let t=document.createElement(`textarea`);t.value=e.dataset.copyValue,t.setAttribute(`readonly`,``),t.style.position=`fixed`,t.style.opacity=`0`,document.body.append(t),t.select();let n=document.execCommand(`copy`);t.remove(),n?this.showCopiedState(e):e.querySelector(`span`).textContent=`Виділи вручну`}showCopiedState(e){e.classList.add(`is-copied`),e.querySelector(`span`).textContent=`Скопійовано`,window.setTimeout(()=>{e.classList.remove(`is-copied`),e.querySelector(`span`).textContent=`Копіювати`},1600)}},t=document.querySelector(`[data-bank-transfer-page]`);t&&new e(t).init();